            var cancelled=acceptCancellation(parties.buyer(),donor.units().stream().map(u->Map.<String,Object>of("itemId",u.orderItemId(),"ordinal",u.ordinal())).toList(),"mixed-cancel");UUID claim=UUID.fromString(cancelled.path("claimId").asText()),itemAttempt=UUID.fromString(cancelled.path("refundAttemptId").asText());runCancellationJob("REFUND_SUBMIT.v1",itemAttempt);runCancellationJob("REFUND_RESULT_RECORDED.v1",itemAttempt);
