    @Test void directAndAutomaticConfirmationFactsCloseMixedReturnsInBothOrders() throws Exception {
        for(boolean returnFirst:List.of(true,false)){for(boolean automatic:List.of(false,true)){
            var f=physicalReturn("d-b-last-"+returnFirst+"-"+automatic,1,true);String number=f.parties().buyer().order().orderNumber();UUID seller=f.parties().shipment().sellerOrderId();if(returnFirst){settleSellerReturnItem(f);runCancellationJob("SELLER_AFTERCARE_REEVALUATE.v1",seller);assertEquals("COMPLETED",jdbc.queryForObject("SELECT state FROM marketplace.claim_return_request WHERE id=:id",Map.of("id",f.accepted().returnId()),String.class));}
            var view=confirmations().get(number,shipmentAuthority(f.parties().buyer()));var selected=view.units().stream().filter(com.example.marketplace.order.api.OrderConfirmations.Eligibility::eligible).map(com.example.marketplace.order.api.OrderConfirmations.Eligibility::unit).toList();assertEquals(3,selected.size());com.example.marketplace.order.api.OrderConfirmations.Result direct=null;var command=new com.example.marketplace.order.api.OrderConfirmations.Command("last-confirm",view.revision(),selected);
            if(automatic){for(var u:selected){var due=view.units().stream().filter(e->e.unit().equals(u)).findFirst().orElseThrow().dueAt();runConfirmation(confirmationJob(u,0),Clock.fixed(due.plusNanos(1000),ZoneOffset.UTC));}}else{direct=confirmations().confirm(number,shipmentAuthority(f.parties().buyer()),command);assertEquals("DIRECT",direct.cause());}
            assertEquals("PAID",orders().find(number).state(),"B succeeds immediately; RETURN-mixed closure waits for the current retained projection");var confirmationIds=jdbc.queryForList("SELECT id FROM marketplace.order_confirmation WHERE order_id=:id ORDER BY id",Map.of("id",f.parties().buyer().order().id()),UUID.class);assertEquals(automatic?3:1,confirmationIds.size());
            for(UUID confirmation:confirmationIds){runCancellationJob("ORDER_CONFIRMATION_RECORDED",confirmation);assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.job WHERE type='SELLER_AFTERCARE_REEVALUATE.v1' AND dedupe_key=:key AND payload=:payload",Map.of("key","seller-aftercare:"+seller+":confirmation:"+confirmation,"payload","CONFIRMATION|"+confirmation),Integer.class),"real B fact must fan out to the seller evaluator");runCancellationJob("SELLER_AFTERCARE_REEVALUATE.v1",seller);}
            if(!returnFirst){settleSellerReturnItem(f);runCancellationJob("SELLER_AFTERCARE_REEVALUATE.v1",seller);}assertEquals("CLOSED",orders().find(number).state());assertEquals("CONFIRMED_UNITS_REMAIN",jdbc.queryForObject("SELECT d.reason FROM marketplace.claim_seller_shipping_current c JOIN marketplace.claim_seller_shipping_decision d ON d.id=c.decision_id WHERE c.seller_order_id=:id",Map.of("id",seller),String.class));assertEquals("RETAINED",jdbc.queryForObject("SELECT d.state FROM marketplace.claim_seller_shipping_current c JOIN marketplace.claim_seller_shipping_decision d ON d.id=c.decision_id WHERE c.seller_order_id=:id",Map.of("id",seller),String.class));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM marketplace.payment_refund_attempt WHERE seller_order_id=:id AND purpose='SHIPPING'",Map.of("id",seller),Integer.class));assertEquals(3,jdbc.queryForObject("SELECT count(*) FROM marketplace.order_unit_lifecycle WHERE seller_order_id=:id AND state='CONFIRMED'",Map.of("id",seller),Integer.class));var stable=returnApplicationParticipants();if(!automatic){assertEquals(direct,confirmations().confirm(number,shipmentAuthority(f.parties().buyer()),command));assertEquals(stable,returnApplicationParticipants());}payments().apply(number,com.example.marketplace.payment.api.PaymentProvider.Result.SUCCEEDED);assertEquals(stable,returnApplicationParticipants());
        }}
    }

    @Test void claimHoldBlocksShipmentWithoutCyclicRead() throws Exception {
        for(boolean holdFirst:List.of(true,false)) { var f=paymentFixture("a-b-dispatch-"+holdFirst,false);var v=paidShipment(f);var unit=new com.example.marketplace.order.api.OrderConfirmations.Unit(v.units().getFirst().orderItemId(),v.units().getFirst().ordinal());UUID hold=UUID.randomUUID(),cause=UUID.randomUUID();if(holdFirst) { new TransactionTemplate(transactionManager).executeWithoutResult(t->confirmations().acquire(f.order().id(),hold,cause,"CANCEL",List.of(unit)));var before=aftercareState();assertEquals(409,assertThrows(com.example.marketplace.order.api.OrderRejected.class,()->shipments().ship(v.id(),shipmentAuthority(f),shipCommand(v,"denied"))).status());assertEquals(before,aftercareState());var split=shipments().split(v.id(),shipmentAuthority(f),splitCommand(v,"held-split",1));var target=shipments().seller(ownSeller(f),shipmentAuthority(f)).stream().filter(s->s.id().equals(split.target().id())).findFirst().orElseThrow();assertEquals(unit.itemId(),target.units().getFirst().orderItemId());assertEquals(unit.ordinal(),target.units().getFirst().ordinal());var remaining=shipments().seller(ownSeller(f),shipmentAuthority(f)).stream().filter(s->s.id().equals(v.id())).findFirst().orElseThrow();shipments().ship(remaining.id(),shipmentAuthority(f),shipCommand(remaining,"unheld"));new TransactionTemplate(transactionManager).executeWithoutResult(t->confirmations().release(f.order().id(),hold,cause,"WITHDRAWN"));shipments().ship(target.id(),shipmentAuthority(f),shipCommand(target,"released")); }else { shipments().ship(v.id(),shipmentAuthority(f),shipCommand(v,"first"));var before=aftercareState();assertEquals(409,assertThrows(com.example.marketplace.order.api.OrderRejected.class,()->new TransactionTemplate(transactionManager).executeWithoutResult(t->confirmations().acquire(f.order().id(),hold,cause,"CANCEL",List.of(unit)))).status());assertEquals(before,aftercareState()); }assertEquals(5,jdbc.queryForObject("SELECT count(*) FROM marketplace.order_dispatch_unit WHERE seller_order_id=:id",Map.of("id",v.sellerOrderId()),Integer.class)); }
        var f=paymentFixture("a-b-dispatch-race",false);var v=paidShipment(f);var unit=new com.example.marketplace.order.api.OrderConfirmations.Unit(v.units().getFirst().orderItemId(),0);var gate=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)) { var h=pool.submit(()->{gate.await();try { new TransactionTemplate(transactionManager).executeWithoutResult(t->confirmations().acquire(f.order().id(),UUID.randomUUID(),UUID.randomUUID(),"CANCEL",List.of(unit)));return 1; }catch(com.example.marketplace.order.api.OrderRejected e) { assertEquals(409,e.status());return 0; }});var s=pool.submit(()->{gate.await();try { shipments().ship(v.id(),shipmentAuthority(f),shipCommand(v,"race"));return 1; }catch(com.example.marketplace.order.api.OrderRejected e) { assertEquals(409,e.status());return 0; }});gate.countDown();assertEquals(1,h.get(10,TimeUnit.SECONDS)+s.get(10,TimeUnit.SECONDS)); }
    }

    @Test void refundReferenceBoundaryPersistsAndExcludesAutomaticConfirmation() throws Exception {
        for(int length:List.of(40,41,200,201)) {
            var f=paymentFixture("b-refund-reference-"+length,false);var v=paidShipment(f);Instant due=Instant.now().plusSeconds(60).truncatedTo(java.time.temporal.ChronoUnit.MICROS);completeShipment(f,v,due.minusSeconds(604800));var raw=v.units().getFirst();var unit=new com.example.marketplace.order.api.OrderConfirmations.Unit(raw.orderItemId(),raw.ordinal());UUID hold=UUID.randomUUID(),cause=UUID.randomUUID();var api=confirmationsWith(Clock.fixed(due.minusSeconds(1),ZoneOffset.UTC),stage->{ });new TransactionTemplate(transactionManager).executeWithoutResult(t->api.acquire(f.order().id(),hold,cause,"RETURN",List.of(unit)));String reference="R".repeat(length);var before=aftercareState();
            if(length==201) {assertEquals(400,assertThrows(com.example.marketplace.order.api.OrderRejected.class,()->new TransactionTemplate(transactionManager).executeWithoutResult(t->api.completeRefund(f.order().id(),hold,cause,reference))).status());assertEquals(before,aftercareState());continue;}
            var result=assertDoesNotThrow(()->new TransactionTemplate(transactionManager).execute(t->api.completeRefund(f.order().id(),hold,cause,reference)),"valid refund reference length="+length);assertEquals("REFUNDED",result.state());assertEquals(reference,jdbc.queryForObject("SELECT outcome FROM marketplace.order_unit_hold WHERE id=:id",Map.of("id",hold),String.class));assertEquals("REFUNDED",jdbc.queryForObject("SELECT state FROM marketplace.order_unit_lifecycle WHERE item_id=:i AND ordinal=:o",Map.of("i",unit.itemId(),"o",unit.ordinal()),String.class));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.order_lifecycle_event WHERE cause_id=:id AND action='REFUNDED'",Map.of("id",hold),Integer.class));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.outbox_event e JOIN marketplace.job j ON j.id=e.job_id WHERE j.dedupe_key=:key",Map.of("key","order-unit-lifecycle:"+hold+":REFUNDED"),Integer.class));var refunded=aftercareState();assertEquals(result,new TransactionTemplate(transactionManager).execute(t->api.completeRefund(f.order().id(),hold,cause,reference)));assertEquals(refunded,aftercareState());runConfirmation(confirmationJob(unit,0),Clock.fixed(due,ZoneOffset.UTC));var after=aftercareState();after.remove("job");refunded.remove("job");assertEquals(refunded,after);assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM marketplace.order_confirmation_unit WHERE item_id=:i AND ordinal=:o",Map.of("i",unit.itemId(),"o",unit.ordinal()),Integer.class));assertEquals("PAID",orders().find(f.order().orderNumber()).state());
        }
    }

