    @Test void exchangeReturnDifferentActualBucketsSumAndRollbackConsentAndApplicationAtomically() throws Exception {
        var f=returnParties("e-fsum",true,2,"5000");var units=f.shipment().units();assertEquals(2,units.size());for(int i=0;i<2;i++){var exchange=exchangeRequest(f,"separate-group-"+i,List.of(units.get(i)));finishActualExchange(f,exchange);}assertNotEquals(exchangeCurrent(units.getFirst().orderItemId(),units.getFirst().ordinal()).delivery().bucketId(),exchangeCurrent(units.getLast().orderItemId(),units.getLast().ordinal()).delivery().bucketId());var physical=inspectedActualFeeReturn(f,units,"two-groups-return");var quote=actualFeeQuote(physical);assertEquals(2,quote.buckets().size());assertEquals("10000",quote.increment());assertTrue(quote.buckets().stream().allMatch(b->b.increment().equals("5000")&&b.assessedTotal().equals("0")&&b.sourceKind()==com.example.marketplace.order.api.PhysicalOrders.BucketKind.EXCHANGE));var before=actualReturnFeeParticipants();var diagnostics=new java.util.ArrayList<Map<String,Object>>();
        for(String mode:List.of("UNIT_SQL_FAILURE","WRONG_REAL_BUCKET")){
            String name="e_fee_"+UUID.randomUUID().toString().replace("-","");String body=mode.equals("UNIT_SQL_FAILURE")?"RAISE EXCEPTION 'E_ACTUAL_FEE_UNIT_SQL_FAILURE' USING ERRCODE='23514';":"NEW.bucket_id=(SELECT b.bucket_id FROM marketplace.claim_exchange_fee_assessment_bucket b WHERE b.assessment_id=NEW.assessment_id AND b.bucket_id<>NEW.bucket_id ORDER BY b.bucket_id LIMIT 1); RETURN NEW;";String sql="CREATE FUNCTION marketplace."+name+"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN "+body+" END $$";jdbc.getJdbcTemplate().execute(sql);jdbc.getJdbcTemplate().execute("CREATE TRIGGER "+name+" BEFORE INSERT ON marketplace.claim_exchange_fee_assessment_unit FOR EACH ROW EXECUTE FUNCTION marketplace."+name+"()");Throwable failure;
            try{failure=assertThrows(org.springframework.dao.DataAccessException.class,()->actualFeeConsent(physical,quote,"sum-consent"));}finally{jdbc.getJdbcTemplate().execute("DROP TRIGGER "+name+" ON marketplace.claim_exchange_fee_assessment_unit");jdbc.getJdbcTemplate().execute("DROP FUNCTION marketplace."+name+"()");}assertEquals(before,actualReturnFeeParticipants(),mode+" must roll back both fee buckets, payment reservation, consent, binding and history/outbox");var root=failure;while(root.getCause()!=null){root=root.getCause();}org.junit.jupiter.api.Assertions.assertInstanceOf(java.sql.SQLException.class,root);assertEquals("23514",((java.sql.SQLException)root).getSQLState());diagnostics.add(Map.of("mode",mode,"sql",sql,"actualError",root.toString(),"fullRollback",true));
        }
        var consent=actualFeeConsent(physical,quote,"sum-consent");assertEquals(10000L,jdbc.queryForObject("SELECT sum(reserved_increment) FROM marketplace.claim_exchange_fee_bucket b JOIN marketplace.claim_delivery_fee_bucket r ON r.id=b.id WHERE r.order_id=:id",Map.of("id",f.buyer().order().id()),Long.class));runCancellationJob("REFUND_SUBMIT.v1",consent.refundAttemptId());runCancellationJob("REFUND_RESULT_RECORDED.v1",consent.refundAttemptId());var actual=new TransactionTemplate(transactionManager).execute(t->context.getBean(com.example.marketplace.payment.api.Refunds.class).get(consent.refundAttemptId()));assertEquals("SUCCEEDED",actual.state());var bound=actualReturnFeeParticipants();
        assertThrows(org.springframework.dao.DataAccessException.class,()->new TransactionTemplate(transactionManager).executeWithoutResult(t->jdbc.update("INSERT INTO marketplace.claim_fee_application(assessment_id,attempt_id,result_version,amount,result_reference,increment,deducted,additional_due,receipt,applied_at) SELECT id,:attempt,:version,refund,:reference,increment,net-refund,additional_due,'{}'::jsonb,clock_timestamp() FROM marketplace.claim_fee_assessment WHERE id=:id",Map.of("id",consent.assessmentId(),"attempt",actual.id(),"version",actual.version(),"reference",actual.resultReference()))));assertEquals(bound,actualReturnFeeParticipants(),"successful actual refund does not authorize receipt-only fee completion");
        for(String stage:List.of("APPLY_RECEIPT","APPLY_BUCKETS","APPLY_STATE","APPLY_HISTORY","APPLY_OUTBOX")){var reached=new AtomicBoolean();var fees=returnFeesWith(point->{if(point.equals(stage)){reached.set(true);throw new java.io.IOException("E_ACTUAL_FEE_"+stage);}});assertThrows(IllegalStateException.class,()->new TransactionTemplate(transactionManager).execute(t->fees.apply(new com.example.marketplace.claim.api.ReturnFees.Apply(consent.assessmentId(),actual.id(),actual.version(),null,null))));assertTrue(reached.get(),stage);assertEquals(bound,actualReturnFeeParticipants(),stage+" entire two-bucket application rollback");diagnostics.add(Map.of("mode",stage,"fullRollback",true));}
        runCancellationJob("RETURN_FINANCE_RESUME.v1",physical.accepted().returnId());assertEquals("APPLIED",jdbc.queryForObject("SELECT state FROM marketplace.claim_fee_assessment WHERE id=:id",Map.of("id",consent.assessmentId()),String.class));assertEquals(10000L,jdbc.queryForObject("SELECT sum(assessed_total) FROM marketplace.claim_exchange_fee_bucket b JOIN marketplace.claim_delivery_fee_bucket r ON r.id=b.id WHERE r.order_id=:id",Map.of("id",f.buyer().order().id()),Long.class));assertEquals(0L,jdbc.queryForObject("SELECT sum(reserved_increment) FROM marketplace.claim_exchange_fee_bucket b JOIN marketplace.claim_delivery_fee_bucket r ON r.id=b.id WHERE r.order_id=:id",Map.of("id",f.buyer().order().id()),Long.class));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_fee_application WHERE assessment_id=:id",Map.of("id",consent.assessmentId()),Integer.class));var applied=actualReturnFeeParticipants();new TransactionTemplate(transactionManager).execute(t->context.getBean(com.example.marketplace.claim.api.ReturnFees.class).apply(new com.example.marketplace.claim.api.ReturnFees.Apply(consent.assessmentId(),actual.id(),actual.version(),null,null)));assertEquals(applied,actualReturnFeeParticipants());java.nio.file.Files.writeString(java.nio.file.Path.of(System.getenv("A3_EVIDENCE"),"e-fee-actual-multiple-bucket-rollback.json"),authMapper.writeValueAsString(Map.of("quote",quote,"consent",consent,"actualRefund",actual,"attempts",diagnostics,"appliedOnce",true,"twoActualGroups",true)));
    }
